pub fn unDeferRecord(import_records: *ImportRecord.List, record_idx: u32) bool {
        if ((record_idx >= import_records.len)) {
            return false;
        }
        const rec = (&import_records.slice()[@as(usize, @intCast(record_idx))]);
        if ((rec.flags.is_internal or (!rec.flags.is_unused))) {
            return false;
        }
        rec.flags.is_unused = false;
        return true;
}

